def describe_network_error(exc: requests.exceptions.RequestException) -> str:
    """Turn a requests exception into a short, human-readable reason.

    Connect/read timeouts and connection errors otherwise render as long
    urllib3 exception chains; callers need a one-line reason, not a traceback.
    """
    if isinstance(exc, requests.exceptions.ConnectTimeout):
        return f"timed out connecting to the server after {DEFAULT_TIMEOUT}s"
    if isinstance(exc, requests.exceptions.ReadTimeout):
        return f"server did not respond within {DEFAULT_TIMEOUT}s"
    if isinstance(exc, requests.exceptions.Timeout):
        return f"request timed out after {DEFAULT_TIMEOUT}s"
    if isinstance(exc, requests.exceptions.ConnectionError):
        lowered = str(exc).lower()
        if any(
            marker in lowered
            for marker in (
                "name or service not known",
                "nodename nor servname",
                "temporary failure in name resolution",
                "getaddrinfo failed",
            )
        ):
            return "could not resolve server hostname"
        if "connection refused" in lowered:
            return "connection refused"
        return f"connection error: {exc}"
    return str(exc)


def _describe_file_error(exc: Exception) -> str:
    if isinstance(exc, requests.exceptions.RequestException):
        return describe_network_error(exc)
    return str(exc)

